const lockWorkspace = `-- name: LockWorkspace :one
SELECT id FROM workspaces WHERE id = $1 FOR UPDATE
`

// Locks the workspace row. An operation insert needs a share lock on it for its foreign key, so
// it waits for the transaction that holds this.
func (q *Queries) LockWorkspace(ctx context.Context, id string) (string, error) {
	row := q.db.QueryRow(ctx, lockWorkspace, id)
	var id_2 string
	err := row.Scan(&id_2)
	return id_2, err
}

const markWorkspaceIdleSuspended = `-- name: MarkWorkspaceIdleSuspended :exec
UPDATE workspaces SET idle_suspended_at = now(), updated_at = now() WHERE id = $1
`

func (q *Queries) MarkWorkspaceIdleSuspended(ctx context.Context, id string) error {
	_, err := q.db.Exec(ctx, markWorkspaceIdleSuspended, id)
	return err
}

const pruneWorkspaceOps = `-- name: PruneWorkspaceOps :execrows
DELETE FROM workspace_ops
WHERE kind <> 'create' AND state NOT IN ('pending', 'retrying')
  AND created_at < now() - make_interval(secs => $1::float8)
`

// Finished operations other than the creates (which explain a failed workspace) are not kept.
func (q *Queries) PruneWorkspaceOps(ctx context.Context, keepSeconds float64) (int64, error) {
	result, err := q.db.Exec(ctx, pruneWorkspaceOps, keepSeconds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const retryWorkspaceOp = `-- name: RetryWorkspaceOp :execrows
UPDATE workspace_ops
SET state = 'retrying', failures = failures + 1,
    first_failed_at = coalesce(first_failed_at, now()), last_error = $4,
    next_attempt_at = now() + make_interval(secs => $5::float8),
    lease_owner = NULL, lease_until = NULL
WHERE id = $1 AND lease_owner = $2 AND attempts = $3 AND state IN ('pending', 'retrying')
`

type RetryWorkspaceOpParams struct {
	ID           string
	LeaseOwner   *string
	Attempts     int32
	LastError    *string
	DelaySeconds float64
}

// Records a transient failure and schedules the next attempt.
func (q *Queries) RetryWorkspaceOp(ctx context.Context, arg RetryWorkspaceOpParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryWorkspaceOp,
		arg.ID,
		arg.LeaseOwner,
		arg.Attempts,
		arg.LastError,
		arg.DelaySeconds,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const touchWorkspace = `-- name: TouchWorkspace :execrows
UPDATE workspaces SET last_active_at = now(), updated_at = now() WHERE id = $1
`

func (q *Queries) TouchWorkspace(ctx context.Context, id string) (int64, error) {
	result, err := q.db.Exec(ctx, touchWorkspace, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const workspaceCreateAttempted = `-- name: WorkspaceCreateAttempted :one
SELECT EXISTS (
    SELECT 1 FROM workspace_ops WHERE workspace_id = $1 AND kind = 'create' AND attempts > 0)
`

// Whether a create was ever sent: kagent may then own a Session Mainloop has not recorded.
func (q *Queries) WorkspaceCreateAttempted(ctx context.Context, workspaceID string) (bool, error) {
	row := q.db.QueryRow(ctx, workspaceCreateAttempted, workspaceID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
